using System;
using System.Globalization;
using System.Collections.Generic;
using System.Linq;
using System.IO;

class Program
{
    static void Main()
    {
        CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
        const string path = "practice-records.json";
        var students = new List<Record>();
        try { if (File.Exists(path)) { if (new FileInfo(path).Length > 65536) throw new InvalidDataException("File too large"); students = System.Text.Json.JsonSerializer.Deserialize<List<Record>>(File.ReadAllText(path)) ?? new(); } }
        catch (Exception ex) when (ex is IOException || ex is System.Text.Json.JsonException) { Console.WriteLine("Invalid practice file; inspect it before continuing"); return; }
        if (students.Any(s => s is null || !Valid(s)) || students.Select(s => s.Id).Distinct().Count() != students.Count) { Console.WriteLine("Invalid or duplicate saved records"); return; }
        for (int step = 0; step < 100; step++)
        {
            Console.WriteLine("1 Add | 2 View | 3 Search | 4 Edit | 5 Delete | 0 Exit");
            string choice = Console.ReadLine() ?? "0"; if (choice == "0") break;
            if (choice == "2") { foreach (var s in students) Console.WriteLine($"{s.Id}: {s.Name} ({s.Course})"); continue; }
            if (!int.TryParse(Console.ReadLine(), out int id) || id <= 0) { Console.WriteLine("Invalid ID"); continue; }
            var existing = students.FirstOrDefault(s => s.Id == id);
            if (choice == "3") { Console.WriteLine(existing is null ? "Not found" : existing.Name); continue; }
            if (choice == "5") { if (existing is not null && Console.ReadLine() == "YES") students.Remove(existing); else Console.WriteLine("Deletion not confirmed"); }
            else if (choice == "1" || choice == "4")
            {
                if ((choice == "1" && existing is not null) || (choice == "4" && existing is null)) { Console.WriteLine("Duplicate ID or record not found"); continue; }
                var record = new Record {Id=id, Name=(Console.ReadLine() ?? "").Trim(), Course=(Console.ReadLine() ?? "").Trim()};
                if (!Valid(record) || students.Count >= 100 && choice == "1") { Console.WriteLine("Invalid record or capacity reached"); continue; }
                if (existing is not null) students.Remove(existing); students.Add(record);
            }
            else { Console.WriteLine("Unknown option"); continue; }
            try { File.WriteAllText(path, System.Text.Json.JsonSerializer.Serialize(students)); } catch (IOException) { Console.WriteLine("Save failed; retry before exiting"); }
        }
    }
    public class Record { public int Id {get;set;} public string Name {get;set;} = ""; public string Course {get;set;} = ""; }
    static bool Valid(Record s) => s.Id > 0 && !string.IsNullOrWhiteSpace(s.Name) && s.Name.Length <= 100 && (s.Course == "IT" || s.Course == "CS");
}

