using System.Threading.Tasks;
using Microsoft.Data.Sqlite;
using System.Security.Cryptography;
class Program
{
    static async Task Main()
    {
        CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
        const string database = "practice-sis.sqlite";
        using var connection = new SqliteConnection($"Data Source={database}"); connection.Open();
        using (var schema = connection.CreateCommand()) { schema.CommandText = "CREATE TABLE IF NOT EXISTS Users(Name TEXT PRIMARY KEY, Salt TEXT NOT NULL, Hash TEXT NOT NULL, Role TEXT CHECK(Role IN ('admin','viewer'))); CREATE TABLE IF NOT EXISTS Students(Id INTEGER PRIMARY KEY, Name TEXT NOT NULL, Course TEXT NOT NULL, Average REAL CHECK(Average BETWEEN 0 AND 100), CreatedUtc TEXT NOT NULL)"; schema.ExecuteNonQuery(); }
        // Provision a practice administrator only if the users table is empty. Supply the secret outside source.
        using (var count = connection.CreateCommand())
        {
            count.CommandText = "SELECT COUNT(*) FROM Users";
            if (Convert.ToInt64(count.ExecuteScalar()) == 0)
            {
                string? user = Environment.GetEnvironmentVariable("PRACTICE_ADMIN_NAME");
                string? secret = Environment.GetEnvironmentVariable("PRACTICE_ADMIN_PASSWORD");
                if (string.IsNullOrWhiteSpace(user) || string.IsNullOrEmpty(secret) || secret.Length < 14) { Console.WriteLine("Provision a fictional practice admin through private configuration first"); return; }
                byte[] salt = RandomNumberGenerator.GetBytes(16); byte[] hash = Rfc2898DeriveBytes.Pbkdf2(secret, salt, 310000, HashAlgorithmName.SHA256, 32);
                using var provision = connection.CreateCommand(); provision.CommandText = "INSERT INTO Users(Name,Salt,Hash,Role) VALUES(@Name,@Salt,@Hash,'admin')";
                provision.Parameters.AddWithValue("@Name", user.Trim()); provision.Parameters.AddWithValue("@Salt", Convert.ToBase64String(salt)); provision.Parameters.AddWithValue("@Hash", Convert.ToBase64String(hash)); provision.ExecuteNonQuery();
            }
        }
        string? role = null;
        for (int attempt = 0; attempt < 3 && role is null; attempt++)
        {
            Console.WriteLine("Practice login: username then password (private stdin only)");
            string username = Console.ReadLine() ?? ""; string password = Console.ReadLine() ?? "";
            using var login = connection.CreateCommand(); login.CommandText = "SELECT Salt,Hash,Role FROM Users WHERE Name=@Name"; login.Parameters.AddWithValue("@Name", username);
            using var user = login.ExecuteReader();
            if (user.Read()) { byte[] actual = Rfc2898DeriveBytes.Pbkdf2(password, Convert.FromBase64String(user.GetString(0)), 310000, HashAlgorithmName.SHA256, 32); if (CryptographicOperations.FixedTimeEquals(actual, Convert.FromBase64String(user.GetString(1)))) role = user.GetString(2); }
            if (role is null) Console.WriteLine("Invalid credentials");
        }
        if (role is null) return;
        for (int action = 0; action < 100; action++)
        {
            Console.WriteLine("1 Dashboard | 2 List/report | 3 Search | 4 Add | 5 Edit | 6 Delete | 0 Logout");
            string choice = Console.ReadLine() ?? "0"; if (choice == "0") { role = null; Console.WriteLine("Logged out"); break; }
            if (choice == "1")
            {
                using var summary = connection.CreateCommand(); summary.CommandText = "SELECT COUNT(*),COALESCE(SUM(CASE WHEN Average>=75 THEN 1 ELSE 0 END),0) FROM Students";
                using var rows = summary.ExecuteReader(); if (rows.Read()) Console.WriteLine($"Total: {rows.GetInt32(0)}; passing: {rows.GetInt32(1)}; failing: {rows.GetInt32(0)-rows.GetInt32(1)}"); continue;
            }
            if (choice == "2" || choice == "3")
            {
                using var report = connection.CreateCommand();
                report.CommandText = choice == "2" ? "SELECT Id,Name,Course,Average FROM Students ORDER BY Average DESC,Id LIMIT 100" : "SELECT Id,Name,Course,Average FROM Students WHERE instr(lower(Name),lower(@Search))>0 ORDER BY Id LIMIT 100";
                if (choice == "3") report.Parameters.AddWithValue("@Search", (Console.ReadLine() ?? "").Trim());
                using var rows = report.ExecuteReader(); while (rows.Read()) Console.WriteLine($"{rows.GetInt32(0)}: {rows.GetString(1)} ({rows.GetString(2)}) {rows.GetDouble(3):F2}"); continue;
            }
            if (role != "admin") { Console.WriteLine("Admin role required"); continue; }
            if (choice != "4" && choice != "5" && choice != "6") { Console.WriteLine("Unknown option"); continue; }
            if (!int.TryParse(Console.ReadLine(), out int id) || id <= 0) { Console.WriteLine("Invalid ID"); continue; }
            using var command = connection.CreateCommand(); command.Parameters.AddWithValue("@Id", id);
            if (choice == "6") { if (Console.ReadLine() != "YES") { Console.WriteLine("Deletion canceled"); continue; } command.CommandText = "DELETE FROM Students WHERE Id=@Id"; }
            else
            {
                string name = (Console.ReadLine() ?? "").Trim(); string course = (Console.ReadLine() ?? "").Trim();
                if (name.Length == 0 || name.Length > 100 || (course != "IT" && course != "CS") || !double.TryParse(Console.ReadLine(), NumberStyles.Float, CultureInfo.InvariantCulture, out double average) || !double.IsFinite(average) || average < 0 || average > 100) { Console.WriteLine("Invalid student record"); continue; }
                command.Parameters.AddWithValue("@Name", name); command.Parameters.AddWithValue("@Course", course); command.Parameters.AddWithValue("@Average", average);
                command.CommandText = choice == "4" ? "INSERT INTO Students(Id,Name,Course,Average,CreatedUtc) VALUES(@Id,@Name,@Course,@Average,@Created)" : "UPDATE Students SET Name=@Name,Course=@Course,Average=@Average WHERE Id=@Id";
                if (choice == "4") command.Parameters.AddWithValue("@Created", DateTime.UtcNow.ToString("O"));
            }
            try { Console.WriteLine($"Affected: {command.ExecuteNonQuery()}"); } catch (SqliteException) { Console.WriteLine("Database change failed; check ID and practice constraints"); }
        }
        await Task.CompletedTask;
    }

}

